tests.script:
on Start(value, heading, target) {
  let floored be :math.floor value
  let flooredCall be :math.floor(value)
  let maxed be :math.max of 2 and 8 and 5
  let turnA be :nav.shortestTurn from: heading to: target
  let turnB be :nav.shortestTurn(from: heading, to: target)
  let northA be heading is :nav.isNorth
  let northB be :nav.isNorth heading
  let vectorTotal be :test.vectorSum :vector3(1m, 2m, 3m)
  let seq be of 10 and 20 and 30
  let asList as :list be of 10 and 20 and 30
  publish Done(floored: floored, flooredCall: flooredCall, maxed: maxed, turnA: turnA, turnB: turnB, northA: northA, northB: northB, vectorTotal: vectorTotal, seqIsSequence: seq is :sequence, seqLen: :len seq, list2: asList[2])
}
